// The wider USDA catalogue: raw and as-sold foods from FoodData Central SR
// Legacy (2018-04), generated by scripts/build-usda-foods.mjs straight from
// the published CSV (see usdaFoodsData.ts). Each has its FDC id as sourceRef,
// and any nutrient USDA did not measure is listed as unknown, never a false 0.
// Meat, fish, eggs, grains and dried beans that USDA also lists cooked carry a
// yield derived from that pair (protein- or dry-matter-anchored, see the
// script); everything else uses the category default until the person weighs
// a cook.
import { NOT_COOKED, type Category, type CookMethod, type Ingredient, type NutrientKey, type NutrientProfile } from '../core/types';
import { USDA_ROWS } from './usdaFoodsData';

const zero: NutrientProfile = {
  kcal: 0, protein: 0, carbs: 0, fibre: 0, fat: 0,
  potassium: 0, iron: 0, magnesium: 0, zinc: 0, calcium: 0, sodium: 0,
};

export const USDA_FOODS: readonly Ingredient[] = USDA_ROWS.map(
  ([id, name, category, per, unknown, absorbsWater, asIs, ref, yields]): Ingredient => ({
    id,
    name,
    category: category as Category,
    per100gRaw: { ...zero, ...(per as Partial<NutrientProfile>) },
    publishedYield: { ...(yields as Partial<Record<CookMethod, number>>) },
    absorbsWater: absorbsWater === 1,
    ...(asIs === 1 ? { defaultMethod: NOT_COOKED } : {}),
    ...(unknown.length === 0 ? {} : { unknownNutrients: [...unknown] as NutrientKey[] }),
    source: 'usda',
    sourceRef: ref,
    archived: false,
  }),
);
